import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse(`{"title":"Technology Choices & Decisions","description":"Hearth's tradeoffs between TypeScript, Node.js, Rust, Go, Python, and frontend frameworks.","frontmatter":{"title":"Technology Choices & Decisions","description":"Hearth's tradeoffs between TypeScript, Node.js, Rust, Go, Python, and frontend frameworks.","outline":[2,3]},"headers":[],"relativePath":"en/design/technology-selection.md","filePath":"en/design/technology-selection.md","lastUpdated":1793855206000}`),n={name:"en/design/technology-selection.md"};function s(i,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<p class="eyebrow">TECHNOLOGY</p><h1 id="technology-choices-decisions" tabindex="-1">Technology Choices &amp; Decisions <a class="header-anchor" href="#technology-choices-decisions" aria-label="Permalink to &quot;Technology Choices &amp; Decisions&quot;">​</a></h1><p class="lead">Technology choices start from system constraints, not language preferences: Hearth must run for the long term, recover from failure, stay auditable, and share one protocol across its TypeScript frontend, CLI, executors, and control plane.</p><h2 id="decision-at-a-glance" tabindex="-1">Decision at a Glance <a class="header-anchor" href="#decision-at-a-glance" aria-label="Permalink to &quot;Decision at a Glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Decision</th><th>Rationale</th></tr></thead><tbody><tr><td>Core language</td><td>TypeScript</td><td>Control plane, Durable Harness, CLI, Web, and executor adapters share types and schemas</td></tr><tr><td>Service runtime</td><td>Node.js 22+</td><td>Runs <code>hearthd</code> and the CLI; no microservices in the first stage</td></tr><tr><td>Server framework</td><td>Fastify or Hono</td><td>HTTP API, SSE, health checks, and process entry point</td></tr><tr><td>Database</td><td>SQLite WAL + migrations</td><td>Single-user, local-first, single-writer; no external database yet</td></tr><tr><td>Schema</td><td>Zod / JSON Schema</td><td>Runtime validation and versioned contracts for events, approvals, and Effects</td></tr><tr><td>Web</td><td>React + Vite + PWA</td><td>Task cards, approvals, artifacts, takeover, and mobile entry point</td></tr><tr><td>Realtime</td><td>SSE first</td><td>Simpler than WebSocket for server-side projection updates</td></tr><tr><td>Documents and data</td><td>Python sidecar</td><td>Parsing, OCR, spreadsheets, batch jobs, and evaluation scripts use mature libraries</td></tr><tr><td>Native components</td><td>Rust where needed</td><td>Sandbox Supervisor, device agents, crypto, and other boundary components</td></tr></tbody></table><p>The core judgment is: <strong>TypeScript is the primary language, Node.js is the runtime, React and Vite are the frontend implementation, and Python and Rust are boundary capabilities.</strong> This is a modular monolith with a small number of explicit sidecars, not a multilingual microservice system.</p><h2 id="typescript-is-not-node-js" tabindex="-1">TypeScript Is Not Node.js <a class="header-anchor" href="#typescript-is-not-node-js" aria-label="Permalink to &quot;TypeScript Is Not Node.js&quot;">​</a></h2><p>TypeScript and Node.js live at different layers and are not alternatives:</p><ul><li><strong>TypeScript is a language.</strong> It adds static types, interfaces, generics, union types, and type checking to JavaScript. The source eventually becomes JavaScript.</li><li><strong>Node.js is a runtime.</strong> It is built on V8 and libuv and provides files, networking, processes, HTTP, timers, and other system capabilities.</li><li><strong>TypeScript does not provide memory safety, concurrency scheduling, or process isolation.</strong> It constrains development-time types; runtime input still needs Zod, JSON Schema, or explicit validation.</li><li><strong>Node.js does not type-check.</strong> Recent Node versions can strip some TypeScript syntax, but type errors still require <code>tsc</code> or an editor.</li></ul><p>When this project says “use TypeScript,” it means: <strong>write the control plane, CLI, Web, and executor code in TypeScript, run server code on Node.js, build the browser with Vite, and serve HTTP and SSE through Fastify/Hono.</strong> See <a href="/hearth-os/en/reference/engineering.html">Engineering Delivery and Repository Structure</a> for the full stack.</p><h2 id="why-typescript-remains-the-primary-language" tabindex="-1">Why TypeScript Remains the Primary Language <a class="header-anchor" href="#why-typescript-remains-the-primary-language" aria-label="Permalink to &quot;Why TypeScript Remains the Primary Language&quot;">​</a></h2><h3 id="shared-protocols-are-the-largest-structural-benefit" tabindex="-1">Shared protocols are the largest structural benefit <a class="header-anchor" href="#shared-protocols-are-the-largest-structural-benefit" aria-label="Permalink to &quot;Shared protocols are the largest structural benefit&quot;">​</a></h3><p>Hearth&#39;s <code>Task</code>, <code>Ticket</code>, <code>Run</code>, <code>Event</code>, <code>Approval</code>, <code>Effect</code>, <code>Receipt</code>, and <code>Artifact</code> appear in the server, CLI, browser, and tests. With TypeScript on both sides, these contracts can live in a shared package that produces both runtime validation and static types.</p><p>If the backend moved to Rust, the frontend would still need TypeScript types and the backend would need Rust types. JSON Schema, OpenAPI, Protobuf, or N-API boundaries could bridge them, but would add version drift, serialization differences, and another debugging path.</p><h3 id="hearth-orchestrates-work-rather-than-computing-it" tabindex="-1">Hearth orchestrates work rather than computing it <a class="header-anchor" href="#hearth-orchestrates-work-rather-than-computing-it" aria-label="Permalink to &quot;Hearth orchestrates work rather than computing it&quot;">​</a></h3><p>The control plane handles state transitions, policy decisions, scheduling, event writes, SSE, and external process orchestration. These are I/O-heavy tasks. Node&#39;s event loop and non-blocking I/O are sufficient, while genuinely CPU-heavy work can move to workers, the Python sidecar, or a Sandbox.</p><p>The current target is a single-user, local-first deployment with SQLite WAL and a single <code>hearthd</code> process. At this scale, Rust&#39;s performance and memory advantages are not the bottleneck. Cross-language complexity would move attention away from task correctness and toward FFI, async runtimes, and build tooling. See <a href="/hearth-os/en/architecture/overview.html">Architecture &amp; Data Flow</a>.</p><h3 id="the-ecosystem-shortens-the-integration-path" tabindex="-1">The ecosystem shortens the integration path <a class="header-anchor" href="#the-ecosystem-shortens-the-integration-path" aria-label="Permalink to &quot;The ecosystem shortens the integration path&quot;">​</a></h3><p>An Agent OS connects to Codex CLI, MCP servers, email and calendar APIs, Playwright, PWA, SSE, SQLite, process supervision, and testing tools. TypeScript/Node has mature libraries, examples, and debugging support for these integrations. Rust would usually need another adapter or process boundary.</p><h3 id="single-writer-and-event-sourcing-are-language-independent" tabindex="-1">Single-writer and event sourcing are language-independent <a class="header-anchor" href="#single-writer-and-event-sourcing-are-language-independent" aria-label="Permalink to &quot;Single-writer and event sourcing are language-independent&quot;">​</a></h3><p>Hearth&#39;s reliability comes from the Event Log, outbox, leases, fencing tokens, idempotency keys, and recovery tests, not from a language&#39;s memory model. Rust can eliminate some memory errors at compile time, but it cannot guarantee task state machines, approval scope, or side-effect idempotency.</p><h3 id="ai-coding-changes-throughput-not-architectural-constraints" tabindex="-1">AI coding changes throughput, not architectural constraints <a class="header-anchor" href="#ai-coding-changes-throughput-not-architectural-constraints" aria-label="Permalink to &quot;AI coding changes throughput, not architectural constraints&quot;">​</a></h3><p>AI coding lowers the cost of typing, but not the cost of requirement clarification, protocol evolution, integration, or human review. The Rust compiler catches more local errors, but it cannot decide whether a task should run automatically or whether an external effect is authorized. Semantic correctness, recoverability, and security boundaries still require design, testing, and review.</p><h2 id="boundaries-for-rust-go-and-python" tabindex="-1">Boundaries for Rust, Go, and Python <a class="header-anchor" href="#boundaries-for-rust-go-and-python" aria-label="Permalink to &quot;Boundaries for Rust, Go, and Python&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Language</th><th>Strength</th><th>Role in Hearth</th></tr></thead><tbody><tr><td>TypeScript</td><td>Shared frontend/backend types, broad ecosystem, fast iteration</td><td>Control plane, Harness, CLI, Web, executor adapters</td></tr><tr><td>Rust</td><td>Memory safety, low overhead, strong types, single binary</td><td>Optional Sandbox Supervisor, device agent, crypto, and low-level boundary components</td></tr><tr><td>Go</td><td>Simple concurrency, single binary, easy deployment</td><td>Not selected now; revisit if the project moves to a high-concurrency cloud service</td></tr><tr><td>Python</td><td>Mature document, data, OCR, ML, and evaluation ecosystem</td><td><code>sidecars/docdata</code>, offline processing, and evaluation scripts</td></tr></tbody></table><p>Revisit Rust if any of these conditions becomes true:</p><ul><li>Target devices cannot run Node.js reliably, or a single native binary is required;</li><li>A large amount of untrusted code must run in-process and memory isolation becomes a core security boundary;</li><li>Local event volume, file processing, or concurrent tasks grow far beyond a single-user MVP;</li><li>The team can maintain a long-lived Rust async and multi-crate codebase.</li></ul><p>Even then, the better route is <strong>Rust boundary components plus a TypeScript control plane</strong>, not an immediate rewrite. Events and APIs should remain language-neutral so implementations can be replaced later.</p><h2 id="frontend-full-stack-typescript-still-uses-a-framework" tabindex="-1">Frontend: Full-Stack TypeScript Still Uses a Framework <a class="header-anchor" href="#frontend-full-stack-typescript-still-uses-a-framework" aria-label="Permalink to &quot;Frontend: Full-Stack TypeScript Still Uses a Framework&quot;">​</a></h2><p>“Full-stack TypeScript” means the frontend and backend share one language. It does not mean avoiding UI frameworks or build tools. The layers are:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Choice</th><th>Role</th></tr></thead><tbody><tr><td>Language</td><td>TypeScript</td><td>Business logic, components, types, and protocols</td></tr><tr><td>UI</td><td>React</td><td>Components, state binding, routing, and interaction</td></tr><tr><td>Build</td><td>Vite</td><td>Compile TS/TSX, hot reload, bundling, and PWA</td></tr><tr><td>Runtime</td><td>Browser / Node.js</td><td>Web runs in the browser; <code>hearthd</code> runs on Node</td></tr><tr><td>Server framework</td><td>Fastify / Hono</td><td>HTTP, SSE, and the server entry point</td></tr></tbody></table><h3 id="why-react" tabindex="-1">Why React <a class="header-anchor" href="#why-react" aria-label="Permalink to &quot;Why React&quot;">​</a></h3><p>Hearth&#39;s frontend is not a static showcase. It is the operating surface for task cards, approvals, artifacts, takeover, live state, and failure recovery. React&#39;s component model, TypeScript support, testing tools, PWA options, and accessibility ecosystem fit this kind of interaction, and match the current <code>React + Vite + PWA</code> choice.</p><p>React is not the only answer. Vue 3 + Vite is also a valid TypeScript solution with a lighter template syntax. If the team is more comfortable with Vue, there is no reason to force a switch. What must stay stable is the server projection, command interface, error semantics, and permission boundary, not the component implementation.</p><h3 id="why-not-native-html-css-javascript" tabindex="-1">Why not native HTML/CSS/JavaScript <a class="header-anchor" href="#why-not-native-html-css-javascript" aria-label="Permalink to &quot;Why not native HTML/CSS/JavaScript&quot;">​</a></h3><p>Native HTML, CSS, and JavaScript are the foundation of the browser, but building the whole application directly requires solving component reuse, state synchronization, routing, form validation, accessibility, live events, and test organization. Hearth&#39;s task cards and approval flows have many shared states and failure paths; hand-written DOM code tends to reinvent an incomplete framework.</p><p>The native stack is a good fit for documentation sites, static pages, and one-off prototypes. Use React or Vue for the real application, and keep the UI as a rendering layer over server projections.</p><h3 id="why-not-next-js-yet" tabindex="-1">Why not Next.js yet <a class="header-anchor" href="#why-not-next-js-yet" aria-label="Permalink to &quot;Why not Next.js yet&quot;">​</a></h3><p>Local-first <code>hearthd</code> already provides HTTP, SSE, and single-writer state. Next.js adds a server runtime, rendering layer, and deployment model that can easily become a second source of truth. For now, a Vite SPA with SSE is simpler and matches the boundary of a single-process local service.</p><h2 id="risks-and-constraints" tabindex="-1">Risks and Constraints <a class="header-anchor" href="#risks-and-constraints" aria-label="Permalink to &quot;Risks and Constraints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Mitigation</th></tr></thead><tbody><tr><td>Node&#39;s single thread is blocked by CPU work</td><td>Move CPU work to workers, the Python sidecar, or a Sandbox; keep the control plane orchestration-only</td></tr><tr><td>TypeScript has no runtime types</td><td>Validate all external input, events, and Effects with Zod / JSON Schema</td></tr><tr><td>Long-running process memory leaks</td><td>Process supervision, soak tests, heap snapshots, and rollback-capable releases</td></tr><tr><td>SQLite write contention</td><td>Single writer, WAL, outbox, leases, and fencing tokens</td></tr><tr><td>npm supply-chain risk</td><td>pnpm lockfile, dependency auditing, minimal dependencies, and release checks</td></tr><tr><td>AI-generated semantic errors</td><td>Contract tests, fault injection, permission-denial tests, and human review</td></tr><tr><td>Cross-language migration cost</td><td>Keep events and APIs language-neutral rather than locking domain protocols into TypeScript</td></tr></tbody></table><h2 id="decision-recap" tabindex="-1">Decision Recap <a class="header-anchor" href="#decision-recap" aria-label="Permalink to &quot;Decision Recap&quot;">​</a></h2><p><strong>Final decision: TypeScript / Node.js is the primary stack, React + Vite + PWA is the frontend, Python is the document and data sidecar, and Rust is reserved for boundary components that genuinely need it.</strong> AI coding makes implementation faster, but does not change the conclusion: speed is not the bottleneck; system boundaries, protocol consistency, recoverability, and security responsibility are.</p>',43)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
